options.customCss:
:root {
    /* الخطوط - استخدام نظام خطوط النظام لتحسين الأداء والرسمية */
    --font-family: 'Inter', 'Segoe UI', Roboto, sans-serif;
    --font-weight-normal: 400;
    --font-weight-medium: 500;
    --font-weight-bold: 600;

    /* أحجام النصوص - تم تعديلها لتكون أكثر تناسقاً */
    --font-size-body: 14px;
    --font-size-label: 13px;
    --font-size-header: 24px;
    --font-size-subheader: 15px;
    --font-size-input: 15px;
    --font-size-html-h1: 32px;

    /* لوحة الألوان الاحترافية (Modern Corporate Palette) */
    --color-background: #f8fafc; /* رمادي فاتح جداً مريح للعين */
    --color-card-bg: #ffffff;
    --color-card-border: #e2e8f0;
    --color-card-shadow: rgba(0, 0, 0, 0.04);

    --color-primary: #2563eb; /* أزرق رسمي احترافي */
    --color-primary-hover: #1d4ed8;

    --color-header: #1e293b; /* كحلي غامق للنصوص الأساسية */
    --color-label: #475569;
    --color-input-text: #1e293b;
    --color-input-border: #cbd5e1;
    --color-focus-border: #3b82f6;

    --color-submit-btn-bg: var(--color-primary);
    --color-submit-btn-text: #ffffff;

    --color-error: #dc2626;
    --color-test-notice-bg: #eff6ff;
    --color-test-notice-text: #1e40af;
    --color-test-notice-border: #bfdbfe;

    /* الحواف والتباعد - لمسة عصرية ناعمة */
    --border-radius-card: 12px;
    --border-radius-input: 8px;
    --padding-card: 32px;
    --container-width: 480px; /* توسيع بسيط لراحة بصرية أكبر */

    /* الظلال */
    --box-shadow-card: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

/* تحسينات إضافية للمظهر العام */
form {
    max-width: var(--container-width);
    margin: 40px auto;
    background: var(--color-card-bg);
    padding: var(--padding-card);
    border-radius: var(--border-radius-card);
    border: 1px solid var(--color-card-border);
    box-shadow: var(--box-shadow-card);
}

input[type="text"], 
input[type="email"], 
input[type="number"], 
textarea, 
select {
    transition: all 0.2s ease-in-out;
    border: 1px solid var(--color-input-border);
    padding: 12px 16px;
    font-weight: var(--font-weight-normal);
}

input:focus {
    outline: none;
    border-color: var(--color-focus-border);
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

button[type="submit"] {
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.5px;
    text-transform: uppercase;
    transition: background 0.3s ease;
    cursor: pointer;
    border: none;
    border-radius: var(--border-radius-input);
}

button[type="submit"]:hover {
    background: var(--color-primary-hover);
}
